fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let mut result = Vec::with_capacity(s.len());
    for chunk in s.chunks(3) {
        if chunk.len() == 3 {
            // For a full block of three, rotate left: [a, b, c] -> [b, c, a]
            result.push(chunk[1]);
            result.push(chunk[2]);
            result.push(chunk[0]);
        } else {
            // Any leftover 1 or 2 elements at the end stay in place
            result.extend_from_slice(chunk);
        }
    }
    result
}

